1	//! Queue attributes: their types, defaults, validation and JSON form.
2	
3	use serde_json::{Value, json};
4	
5	use crate::error::{Error, ErrorCode, Result};
6	use crate::request::Params;
7	
8	const ATTRIBUTE_NAMES: [&str; 7] = [
9	    "VisibilityTimeout",
10	    "DelaySeconds",
11	    "RetentionSeconds",
12	    "Fifo",
13	    "ContentBasedDeduplication",
14	    "DeadLetterQueue",
15	    "MaxReceiveCount",
16	];
17	
18	/// Where messages go after too many deliveries.
19	#[derive(Clone, Debug, PartialEq, Eq)]
20	pub struct DeadLetter {
21	    pub queue: String,
22	    pub max_receive_count: u64,
23	}
24	
25	/// The complete attribute set of a queue.
26	#[derive(Clone, Debug, PartialEq, Eq)]
27	pub struct Attributes {
28	    pub visibility_timeout: u64,
29	    pub delay_seconds: u64,
30	    pub retention_seconds: u64,
31	    pub fifo: bool,
32	    pub content_based_deduplication: bool,
33	    pub dead_letter: Option<DeadLetter>,
34	}
35	
36	impl Default for Attributes {
37	    fn default() -> Self {
38	        Self {
39	            visibility_timeout: 30,
40	            delay_seconds: 0,
41	            retention_seconds: 345_600,
42	            fifo: false,
43	            content_based_deduplication: false,
44	            dead_letter: None,
45	        }
46	    }
47	}
48	
49	impl Attributes {
50	    /// The `Attributes` member of a `GetQueueAttributes` result.
51	    pub fn to_json(&self) -> Value {
52	        let mut json = json!({
53	            "VisibilityTimeout": self.visibility_timeout,
54	            "DelaySeconds": self.delay_seconds,
55	            "RetentionSeconds": self.retention_seconds,
56	            "Fifo": self.fifo,
57	            "ContentBasedDeduplication": self.content_based_deduplication,
58	        });
59	        if let Some(dead_letter) = &self.dead_letter {
60	            json["DeadLetterQueue"] = json!(dead_letter.queue);
61	            json["MaxReceiveCount"] = json!(dead_letter.max_receive_count);
62	        }
63	        json
64	    }
65	
66	    /// Overwrites the attributes that `update` carries and keeps the others.
67	    /// The caller has already validated the update.
68	    pub fn apply(&mut self, update: AttributeUpdate) {
69	        let AttributeUpdate {
70	            visibility_timeout,
71	            delay_seconds,
72	            retention_seconds,
73	            fifo,
74	            content_based_deduplication,
75	            dead_letter_queue,
76	            max_receive_count,
77	        } = update;
78	        self.visibility_timeout = visibility_timeout.unwrap_or(self.visibility_timeout);
79	        self.delay_seconds = delay_seconds.unwrap_or(self.delay_seconds);
80	        self.retention_seconds = retention_seconds.unwrap_or(self.retention_seconds);
81	        self.fifo = fifo.unwrap_or(self.fifo);
82	        self.content_based_deduplication =
83	            content_based_deduplication.unwrap_or(self.content_based_deduplication);
84	        if let (Some(queue), Some(max_receive_count)) = (dead_letter_queue, max_receive_count) {
85	            self.dead_letter = Some(DeadLetter {
86	                queue,
87	                max_receive_count,
88	            });
89	        }
90	    }
91	}
92	
93	/// The attributes a request carries; absent ones are `None`.
94	#[derive(Debug, Default)]
95	pub struct AttributeUpdate {
96	    pub visibility_timeout: Option<u64>,
97	    pub delay_seconds: Option<u64>,
98	    pub retention_seconds: Option<u64>,
99	    pub fifo: Option<bool>,
100	    pub content_based_deduplication: Option<bool>,
101	    pub dead_letter_queue: Option<String>,
102	    pub max_receive_count: Option<u64>,
103	}
104	
105	impl AttributeUpdate {
106	    /// Validates names, types and ranges of an `Attributes` object
107	    /// (SPEC section 2, check 3). `None` stands for an absent object.
108	    pub fn parse(attributes: Option<Params<'_>>) -> Result<Self> {
109	        let Some(p) = attributes else {
110	            return Ok(Self::default());
111	        };
112	        p.reject_unknown(&ATTRIBUTE_NAMES)?;
113	        Ok(Self {
114	            visibility_timeout: p.integer("VisibilityTimeout", 0..=43_200)?,
115	            delay_seconds: p.integer("DelaySeconds", 0..=900)?,
116	            retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
117	            fifo: p.boolean("Fifo")?,
118	            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
119	            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
120	            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
121	        })
122	    }
123	
124	    /// The dead-letter configuration, which must be given completely or not
125	    /// at all.
